                post.client_waiting(i) && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() && post.slots.index(i)) by {
                // For i != j: All fields are unchanged, so this follows from pre.request_stored_inv.
                // For i == j: post.requests[j] == pre.requests[j] (unchanged).
                //   We showed earlier that !pre.request_stored(j) (from combiner_has_inv).
                //   So post.request_stored(j) is also false.
                //   The implication is vacuously true.
                admit() // TODO: formal proof
            };

            // 4. response_stored_inv in post
            // Need: forall |i: nat| post.response_stored(i) ==> post.client_waiting(i) && post.responses[i].rid == post.clients[i].rid && !post.slots[i]
            assert(forall |i: nat| crate::FlatCombiner::response_stored(post, i) ==>
                post.client_waiting(i) && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() && !post.slots.index(i)) by {
                // For i != j: All fields are unchanged, so this follows from pre.response_stored_inv.
                // For i == j: post.responses[j] is now Some(response).
                //   post.clients[j] == pre.clients[j] (still Waiting with rid = pre.clients[j].rid).
                //   We need: response.rid == post.clients[j].rid.
                //   From the transition: response_opt == Option::Some(response.rid).
                //   And response_opt = pre.combiner.get_Responding_elems().index(j as int).
