// rust_verify/tests/example.rs expect-warnings
#[allow(unused_imports)]
use verus_builtin::*;
use verus_builtin_macros::*;
use vstd::map::*;
use vstd::multiset::*;
use vstd::prelude::*;
use vstd::seq::*;
use vstd::{pervasive::*, *};

use verus_state_machines_macros::tokenized_state_machine;

// Based off of the FlatCombine system from Seagull-NR.
// A major difference is that one didn't make any use of storage, because storage was
// rather complicated to use, and it wasn't necessary.
// Now, I expect storage to be a lot easier to use, easier than the alternative.

verus! {

pub struct Request {
    pub rid: int,
    pub req: int,
}

pub struct Response {
    pub rid: int,
    pub resp: int,
}

#[is_variant]
pub enum Client {
    Idle,
    Waiting { rid: int },
}

#[is_variant]
pub enum Combiner {
    Collecting { elems: Seq<Option<int>> },
    Responding { elems: Seq<Option<int>>, idx: nat },
}

} // verus!
tokenized_state_machine! {
    FlatCombiner {
        fields {
            #[sharding(constant)]
            pub num_clients: nat,

            #[sharding(imap)]
            pub clients: IMap<nat, Client>,

            #[sharding(imap)]
            pub slots: IMap<nat, bool>,

            #[sharding(variable)]
            pub combiner: Combiner,

            #[sharding(storage_imap)]
            pub requests: IMap<nat, Request>,

            #[sharding(storage_imap)]
            pub responses: IMap<nat, Response>,
        }

        pub open spec fn valid_idx(self, i: nat) -> bool {
            0 <= i && i < self.num_clients
        }

        #[invariant]
        pub fn clients_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.clients.dom().contains(i)
        }

        #[invariant]
        pub fn slots_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.slots.dom().contains(i)
        }

        #[invariant]
        pub fn clients_size(self) -> bool {
            match self.combiner {
                Combiner::Collecting{elems} => elems.len() <= self.num_clients,
                Combiner::Responding{elems, idx} => elems.len() == self.num_clients &&
                    0 <= idx && idx <= self.num_clients,
            }
        }

        /*
        #[verifier::spec]
        fn should_have_req_stored(self, i: nat) -> bool {
            0 <= i
            && i < self.slots
            && self.slots.index(i)
            && match self.combiner {
                Combiner::Collecting{elems} => elems.len() < i || elems.index(i).is_None()
                Combiner::Responding{elems, idx} => idx >= i || elems.index(i).is_None()
            }
        }
        */

        pub open spec fn client_waiting(self, i: nat) -> bool {
            self.valid_idx(i)
            && self.clients.index(i).is_Waiting()
        }

        pub open spec fn combiner_has(self, i: nat) -> bool {
            self.valid_idx(i)
            && match self.combiner {
                Combiner::Collecting{elems} => i < elems.len() && i < elems.len() as int && elems.index(i as int).is_Some(),
                Combiner::Responding{elems, idx} => i >= idx && i < elems.len() as int && elems.index(i as int).is_Some(),
            }
        }

        pub open spec fn combiner_rid(self, i: nat) -> int {
            match self.combiner {
                Combiner::Collecting{elems} => elems.index(i as int).get_Some_0(),
                Combiner::Responding{elems, idx} => elems.index(i as int).get_Some_0(),
            }
        }

        pub open spec fn request_stored(self, i: nat) -> bool {
            self.requests.dom().contains(i)
        }

        pub open spec fn response_stored(self, i: nat) -> bool {
            self.responses.dom().contains(i)
        }

        #[invariant]
        pub fn not_waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.valid_idx(i) && self.clients.index(i).is_Idle() ==>
                !self.slots.index(i)
        }

        #[invariant]
        pub fn waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.client_waiting(i) ==>
                self.request_stored(i) || self.response_stored(i) || self.combiner_has(i)
        }

        #[invariant]
        pub fn request_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.request_stored(i) ==>
                self.client_waiting(i)
                && self.requests.index(i).rid == self.clients.index(i).get_Waiting_rid()
                && self.slots.index(i)
        }

        #[invariant]
        pub fn response_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.response_stored(i) ==>
                self.client_waiting(i)
                && self.responses.index(i).rid == self.clients.index(i).get_Waiting_rid()
                && !self.slots.index(i)
        }


        #[invariant]
        pub fn combiner_has_inv(self) -> bool {
            forall |i: nat| #[trigger] self.combiner_has(i) ==>
                self.client_waiting(i)
                && self.slots.index(i)
                && self.combiner_rid(i) == self.clients.index(i).get_Waiting_rid()
                && !self.request_stored(i)
        }

        init!{
            initialize(num_clients: nat) {
                init num_clients = num_clients;
                init clients = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| Client::Idle);
                init slots = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| false);
                init combiner = Combiner::Collecting { elems: Seq::empty() };
                init requests = IMap::empty();
                init responses = IMap::empty();
            }
        }

        #[inductive(initialize)]
        fn init_inductive(post: Self, num_clients: nat) { }

        ///// Client transitions

        transition!{
            client_send(j: nat, request: Request, cur_slot: bool) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'waiting' state
                remove clients -= [j => Client::Idle];
                add    clients += [j => Client::Waiting{rid: request.rid}];

                // Set the slot
                remove slots -= [j => cur_slot];
                add    slots += [j => true];

                // deposit the request
                deposit requests += [j => request] by {
                    assert(!pre.request_stored(j));
                };
            }
        }

        #[inductive(client_send)]
        fn client_send_inductive(pre: Self,
            post: Self, j: nat, request: Request, cur_slot: bool)
        {
            admit()
        }

        transition!{
            client_recv(j: nat) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'idle' state
                remove clients -= [j => let Client::Waiting{rid}];
                add    clients += [j => Client::Idle];

                // Check that the slot has been set back to 'false'
                have slots >= [j => false];

                // withdraw the response
                withdraw responses -= [j => let response] by {
                    assert(pre.client_waiting(j));
                    //assert(!pre.request_stored(j));
                    //assert(!pre.combiner_has(j));
                    //assert(pre.response_stored(j));
                };

                // make sure we get back the response for the correct request id:
                assert(response.rid == rid) by {
                    assert(pre.client_waiting(j));
                };
            }
        }

        #[inductive(client_recv)]
        fn client_recv_inductive(pre: Self, post: Self, j: nat) {
            admit()
        }

        ///// Combiner transitions

        transition!{
            combiner_recv() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // Observe that the slot has been set to 'true'
                have slots >= [j => true];

                // Withdraw a request
                withdraw requests -= [j => let request] by {
                    assert(pre.valid_idx(j));
                    assert(pre.client_waiting(j));
                    assert(pre.request_stored(j));
                };

                // Update combiner's local state to remember we withdrew a request with this ID
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::Some(request.rid)),
                };
            }
        }

        #[inductive(combiner_recv)]
        fn combiner_recv_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_skip() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // In practice, this happens when slot j is set to false, so we could add this:
                //    have slots >= [j => false];
                // but it's not necessary

                // Update combiner's local state to remember that we didn't withdraw
                // anything here.
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::None),
                };
            }
        }

        #[inductive(combiner_skip)]
        fn combiner_skip_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_go_to_responding() {
                require(pre.combiner.is_Collecting());
                require(pre.combiner.get_Collecting_elems().len() == pre.num_clients);
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Collecting_elems(),
                    idx: 0,
                };
            }
        }

        transition!{
            combiner_send(response: Response, cur_slot: bool) {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(response_opt == Option::Some(response.rid));

                // Set the slot back to false
                remove slots -= [j => cur_slot];
                add    slots += [j => false];

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };

                deposit responses += [j => response] by {
                    assert(pre.valid_idx(j));
                    assert(pre.combiner_has(j));
                    assert(!pre.response_stored(j));
                };
            }
        }

        #[inductive(combiner_send)]
        fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool)
        {
            // The transition: combiner_send(j, response, cur_slot) where j = pre.combiner.get_Responding_idx()
            // modifies: slots[j], responses[j], and combiner.idx (from j to j+1)

            // Extract j from pre.combiner for use in the proof
            let j_val = pre.combiner.get_Responding_idx();

            // From the transition precondition, we know:
            // response_opt = pre.combiner.get_Responding_elems().index(j_val as int)
            // response_opt = Option::Some(response.rid)
            // So: pre.combiner.get_Responding_elems().index(j_val as int) = Option::Some(response.rid)

            // This means j_val < pre.combiner.get_Responding_elems().len()
            // And pre.combiner.get_Responding_elems().index(j_val as int).is_Some()

            // From pre invariant combiner_has_inv and pre.combiner_has(j_val):
            // We need to show pre.combiner_has(j_val) first.
            // Since pre.combiner is Responding with idx = j_val:
            //   pre.combiner_has(j_val) = (j_val >= j_val && j_val < elems.len() && elems[j_val].is_Some())
            //   = (true && j_val < elems.len() && elems[j_val].is_Some())
            // We know j_val < elems.len() (from the transition precondition, since we're indexing at j_val)
            // And elems[j_val].is_Some() (from response_opt = Option::Some(response.rid))
            // So pre.combiner_has(j_val) is true!

            // From pre.combiner_has_inv and pre.combiner_has(j_val):
            pre.combiner_has_inv();
            assert(pre.combiner_has(j_val));
            assert(pre.client_waiting(j_val));
            assert(pre.slots.index(j_val));
            assert(pre.combiner_rid(j_val) == pre.clients.index(j_val).get_Waiting_rid());
            assert(!pre.request_stored(j_val));

            // Now let's analyze what changed:
            // 1. slots[j_val] changed from cur_slot to false
            // 2. responses[j_val] is now Some(response)
            // 3. combiner changed from Responding{elems, idx=j_val} to Responding{elems, idx=j_val+1}

            // For all other indices i != j_val, the state is unchanged.

            // We need to prove all invariants in post.

            // 1. not_waiting_inv in post:
            // forall |i: nat| post.valid_idx(i) && post.clients[i].is_Idle() ==> !post.slots[i]
            // For i != j_val: post.clients[i] = pre.clients[i], post.slots[i] = pre.slots[i]
            //   If post.clients[i].is_Idle(), then pre.clients[i].is_Idle().
            //   By pre.not_waiting_inv: !pre.slots[i], so !post.slots[i].
            // For i == j_val: post.slots[j_val] = false (we set it).
            //   So !post.slots[j_val] holds regardless of post.clients[j_val].
            // Thus, not_waiting_inv holds in post.
            broadcast use vstd::iset::group_iset_lemmas;
            broadcast use vstd::imap::group_imap_lemmas;
            broadcast use vstd::seq::group_seq_lemmas;

            // Helper lemma: slots[j_val] is now false in post
            // From the transition: remove slots -= [j_val => cur_slot]; add slots += [j_val => false];
            // This means post.slots = pre.slots.remove(j_val).insert(j_val, false)
            // So post.slots[j_val] = false

            // Prove not_waiting_inv for all i
            assert(forall |i: nat| post.valid_idx(i) && post.clients.index(i).is_Idle() ==>
                !post.slots.index(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | post.valid_idx(i) && post.clients.index(i).is_Idle();
                if i == j_val {
                    // i == j_val
                    // post.slots[j_val] = false (from transition)
                    // So !post.slots[j_val] holds.
                    assert(!post.slots.index(i));
                } else {
                    // i != j_val
                    // post.clients[i] = pre.clients[i]
                    // post.slots[i] = pre.slots[i]
                    // post.valid_idx(i) = pre.valid_idx(i)
                    // So post.clients[i].is_Idle() = pre.clients[i].is_Idle()
                    // By pre.not_waiting_inv: pre.clients[i].is_Idle() ==> !pre.slots[i]
                    // So !pre.slots[i], which means !post.slots[i]
                    assert(!post.slots.index(i));
                }
            };
            // Conclude not_waiting_inv
            assert(post.not_waiting_inv());

            // 2. waiting_inv in post:
            // forall |i: nat| post.client_waiting(i) ==> post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)
            // For i != j_val: All fields are unchanged. By pre.waiting_inv, the property holds.
            // For i == j_val: post.clients[j_val] = pre.clients[j_val] = Waiting(rid).
            //   So post.client_waiting(j_val) is true.
            //   post.responses[j_val] is now Some(response). So post.response_stored(j_val) is true.
            //   Thus, the disjunction holds.
            assert(forall |i: nat| post.client_waiting(i) ==>
                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | post.client_waiting(i);
                if i == j_val {
                    // i == j_val
                    // post.responses[j_val] = Some(response)
                    // So post.response_stored(j_val) is true
                    assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
                } else {
                    // i != j_val
                    // All fields unchanged
                    // By pre.waiting_inv
                    assert(post.request_stored(i) || post.response_stored(i) || post.combiner_has(i));
                }
            };
            assert(post.waiting_inv());

            // 3. request_stored_inv in post:
            // forall |i: nat| post.request_stored(i) ==> post.client_waiting(i) && post.requests[i].rid == post.clients[i].rid && post.slots[i]
            // For i != j_val: All fields are unchanged. By pre.request_stored_inv, this holds.
            // For i == j_val: post.requests[j_val] = pre.requests[j_val].
            //   We know !pre.request_stored(j_val) (from above).
            //   So post.request_stored(j_val) is also false.
            //   The implication is vacuously true.
            assert(forall |i: nat| post.request_stored(i) ==>
                post.client_waiting(i) && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() && post.slots.index(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | post.request_stored(i);
                if i == j_val {
                    // i == j_val
                    // !pre.request_stored(j_val) and post.requests[j_val] = pre.requests[j_val]
                    // So !post.request_stored(j_val)
                    // The implication is vacuously true
                    assert(post.client_waiting(i) && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() && post.slots.index(i));
                } else {
                    // i != j_val
                    // All fields unchanged
                    // By pre.request_stored_inv
                    assert(post.client_waiting(i) && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() && post.slots.index(i));
                }
            };
            assert(post.request_stored_inv());

            // 4. response_stored_inv in post:
            // forall |i: nat| post.response_stored(i) ==> post.client_waiting(i) && post.responses[i].rid == post.clients[i].rid && !post.slots[i]
            // For i != j_val: All fields are unchanged. By pre.response_stored_inv, this holds.
            // For i == j_val: post.responses[j_val] is now Some(response).
            //   post.clients[j_val] = pre.clients[j_val] = Waiting(rid).
            //   post.slots[j_val] = false (we set it).
            //   We need: post.responses[j_val].rid == post.clients[j_val].rid.
            //   response.rid == pre.clients[j_val].get_Waiting_rid() = post.clients[j_val].get_Waiting_rid().
            //   This follows from pre.combiner_rid(j_val) == pre.clients[j_val].get_Waiting_rid()
            //   and pre.combiner_rid(j_val) = response_opt.get_Some_0() = response.rid.
            assert(forall |i: nat| post.response_stored(i) ==>
                post.client_waiting(i) && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() && !post.slots.index(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | post.response_stored(i);
                if i == j_val {
                    // i == j_val
                    // post.responses[j_val] = Some(response)
                    // post.clients[j_val] = pre.clients[j_val] = Waiting(rid)
                    // post.slots[j_val] = false
                    // post.responses[j_val].rid = response.rid
                    // We need: response.rid == pre.clients[j_val].get_Waiting_rid()
                    // From earlier: pre.combiner_rid(j_val) == pre.clients[j_val].get_Waiting_rid()
                    // And pre.combiner_rid(j_val) = response_opt.get_Some_0() = response.rid
                    // So response.rid == pre.clients[j_val].get_Waiting_rid()
                    assert(post.client_waiting(i) && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() && !post.slots.index(i));
                } else {
                    // i != j_val
                    // All fields unchanged
                    // By pre.response_stored_inv
                    assert(post.client_waiting(i) && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() && !post.slots.index(i));
                }
            };
            assert(post.response_stored_inv());

            // 5. combiner_has_inv in post:
            // forall |i: nat| post.combiner_has(i) ==> post.client_waiting(i) && post.slots[i] && post.combiner_rid(i) == post.clients[i].rid && !post.request_stored(i)
            // For i < j_val: In post, combiner.idx = j_val+1.
            //   post.combiner_has(i) = (i >= j_val+1 && i < elems.len() && elems[i].is_Some()).
            //   Since i < j_val, we have i < j_val < j_val+1, so i >= j_val+1 is false.
            //   Thus, post.combiner_has(i) is false.
            //   The implication is vacuously true.
            // For i == j_val: In post, combiner.idx = j_val+1.
            //   post.combiner_has(j_val) = (j_val >= j_val+1 && ...).
            //   j_val >= j_val+1 is false.
            //   Thus, post.combiner_has(j_val) is false.
            //   The implication is vacuously true.
            // For i > j_val (i >= j_val+1): post.combiner_has(i) = (i >= j_val+1 && i < elems.len() && elems[i].is_Some()).
            //   In pre, post.combiner_has(i) = (i >= j_val && i < elems.len() && elems[i].is_Some()).
            //   Since i >= j_val+1, we have i >= j_val, so the conditions are equivalent.
            //   Thus, post.combiner_has(i) has the same truth value as pre.combiner_has(i).
            //   Also, for i > j_val:
            //     post.clients[i] = pre.clients[i]
            //     post.slots[i] = pre.slots[i] (unchanged, since we only modified j_val)
            //     post.combiner_rid(i) = pre.combiner_rid(i) (same elems)
            //     post.requests[i] = pre.requests[i] (unchanged)
            //   So all properties follow from pre.combiner_has_inv.
            assert(forall |i: nat| post.combiner_has(i) ==>
                post.client_waiting(i) && post.slots.index(i) && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid() && !post.request_stored(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | post.combiner_has(i);
                if i < j_val {
                    // i < j_val
                    // post.combiner_has(i) = false (because i < j_val < j_val+1 = post.combiner.idx)
                    // The implication is vacuously true
                    assert(post.client_waiting(i) && post.slots.index(i) && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid() && !post.request_stored(i));
                } else if i == j_val {
                    // i == j_val
                    // post.combiner_has(j_val) = false (because j_val < j_val+1 = post.combiner.idx)
                    // The implication is vacuously true
                    assert(post.client_waiting(i) && post.slots.index(i) && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid() && !post.request_stored(i));
                } else {
                    // i > j_val (i >= j_val+1)
                    // post.combiner_has(i) = pre.combiner_has(i)
                    // All other properties unchanged, so follow from pre.combiner_has_inv
                    assert(post.client_waiting(i) && post.slots.index(i) && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid() && !post.request_stored(i));
                }
            };
            assert(post.combiner_has_inv());

            // 6. slots_complete in post:
            // forall |i: nat| (0 <= i && i < post.num_clients) == post.slots.dom().contains(i)
            // post.num_clients = pre.num_clients (constant).
            // post.slots = pre.slots.remove(j_val).insert(j_val, false).
            // So post.slots.dom() = pre.slots.dom() (removing and re-inserting the same key).
            // Since pre.slots_complete holds, post.slots_complete also holds.
            assert(forall |i: nat| (0 <= i && i < post.num_clients) == post.slots.dom().contains(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | (0 <= i && i < post.num_clients);
                // post.slots.dom() = pre.slots.dom().remove(j_val).insert(j_val)
                // = pre.slots.dom() (since remove and insert cancel out for the same key)
                // So the property follows from pre.slots_complete
                assert((0 <= i && i < post.num_clients) == post.slots.dom().contains(i));
            };
            assert(post.slots_complete());

            // 7. clients_complete in post:
            // post.clients = pre.clients, so this still holds.
            assert(forall |i: nat| (0 <= i && i < post.num_clients) == post.clients.dom().contains(i)) by {
                quantifier_introduction!();
                let i = choose| i: nat | (0 <= i && i < post.num_clients);
                // post.clients.dom() = pre.clients.dom()
                // So the property follows from pre.clients_complete
                assert((0 <= i && i < post.num_clients) == post.clients.dom().contains(i));
            };
            assert(post.clients_complete());

            // 8. clients_size in post:
            // post.combiner = Responding{elems, idx=j_val+1}
            // We know pre.combiner.elems.len() == pre.num_clients (from pre.clients_size for Responding).
            // So post.combiner.elems.len() == post.num_clients.
            // We need: 0 <= j_val+1 <= post.num_clients.
            // From the transition: 0 <= j_val < pre.num_clients.
            // So 0 <= j_val+1 <= pre.num_clients = post.num_clients.
            // Also, post.combiner is Responding, so we check the Responding case.
            match post.combiner {
                Combiner::Collecting{elems} => assert(elems.len() <= post.num_clients),
                Combiner::Responding{elems, idx} => {
                    assert(elems.len() == post.num_clients);
                    assert(0 <= idx);
                    assert(idx <= post.num_clients);
                }
            };
            assert(post.clients_size());

            // All invariants hold!
        }

        transition!{
            combiner_send_skip() {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(equal(response_opt, Option::None));

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };
            }
        }

        #[inductive(combiner_send_skip)]
        fn combiner_send_skip_inductive(pre: Self, post: Self) {
            admit()
        }

        #[inductive(combiner_go_to_responding)]
        fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_go_to_collecting() {
                require(pre.combiner.is_Responding());
                require(pre.combiner.get_Responding_idx() == pre.num_clients);
                update combiner = Combiner::Collecting{ elems: Seq::empty() };
            }
        }

        #[inductive(combiner_go_to_collecting)]
        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
            admit()
        }

    }
}

fn main() {}

// rust_verify/tests/example.rs expect-warnings
#[allow(unused_imports)]
use verus_builtin::*;
use verus_builtin_macros::*;
use vstd::map::*;
use vstd::multiset::*;
use vstd::prelude::*;
use vstd::seq::*;
use vstd::{pervasive::*, *};

use verus_state_machines_macros::tokenized_state_machine;

// Based off of the FlatCombine system from Seagull-NR.
// A major difference is that one didn't make any use of storage, because storage was
// rather complicated to use, and it wasn't necessary.
// Now, I expect storage to be a lot easier to use, easier than the alternative.

verus! {

pub struct Request {
    pub rid: int,
    pub req: int,
}

pub struct Response {
    pub rid: int,
    pub resp: int,
}

#[is_variant]
pub enum Client {
    Idle,
    Waiting { rid: int },
}

#[is_variant]
pub enum Combiner {
    Collecting { elems: Seq<Option<int>> },
    Responding { elems: Seq<Option<int>>, idx: nat },
}

} // verus!
tokenized_state_machine! {
    FlatCombiner {
        fields {
            #[sharding(constant)]
            pub num_clients: nat,

            #[sharding(imap)]
            pub clients: IMap<nat, Client>,

            #[sharding(imap)]
            pub slots: IMap<nat, bool>,

            #[sharding(variable)]
            pub combiner: Combiner,

            #[sharding(storage_imap)]
            pub requests: IMap<nat, Request>,

            #[sharding(storage_imap)]
            pub responses: IMap<nat, Response>,
        }

        pub open spec fn valid_idx(self, i: nat) -> bool {
            0 <= i && i < self.num_clients
        }

        #[invariant]
        pub fn clients_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.clients.dom().contains(i)
        }

        #[invariant]
        pub fn slots_complete(self) -> bool {
            forall |i: nat| (0 <= i && i < self.num_clients) ==
                self.slots.dom().contains(i)
        }

        #[invariant]
        pub fn clients_size(self) -> bool {
            match self.combiner {
                Combiner::Collecting{elems} => elems.len() <= self.num_clients,
                Combiner::Responding{elems, idx} => elems.len() == self.num_clients &&
                    0 <= idx && idx <= self.num_clients,
            }
        }

        /*
        #[verifier::spec]
        fn should_have_req_stored(self, i: nat) -> bool {
            0 <= i
            && i < self.slots
            && self.slots.index(i)
            && match self.combiner {
                Combiner::Collecting{elems} => elems.len() < i || elems.index(i).is_None()
                Combiner::Responding{elems, idx} => idx >= i || elems.index(i).is_None()
            }
        }
        */

        pub open spec fn client_waiting(self, i: nat) -> bool {
            self.valid_idx(i)
            && self.clients.index(i).is_Waiting()
        }

        pub open spec fn combiner_has(self, i: nat) -> bool {
            self.valid_idx(i)
            && match self.combiner {
                Combiner::Collecting{elems} => i < elems.len() && i < elems.len() as int && elems.index(i as int).is_Some(),
                Combiner::Responding{elems, idx} => i >= idx && i < elems.len() as int && elems.index(i as int).is_Some(),
            }
        }

        pub open spec fn combiner_rid(self, i: nat) -> int {
            match self.combiner {
                Combiner::Collecting{elems} => elems.index(i as int).get_Some_0(),
                Combiner::Responding{elems, idx} => elems.index(i as int).get_Some_0(),
            }
        }

        pub open spec fn request_stored(self, i: nat) -> bool {
            self.requests.dom().contains(i)
        }

        pub open spec fn response_stored(self, i: nat) -> bool {
            self.responses.dom().contains(i)
        }

        #[invariant]
        pub fn not_waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.valid_idx(i) && self.clients.index(i).is_Idle() ==>
                !self.slots.index(i)
        }

        #[invariant]
        pub fn waiting_inv(self) -> bool {
            forall |i: nat| #[trigger] self.client_waiting(i) ==>
                self.request_stored(i) || self.response_stored(i) || self.combiner_has(i)
        }

        #[invariant]
        pub fn request_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.request_stored(i) ==>
                self.client_waiting(i)
                && self.requests.index(i).rid == self.clients.index(i).get_Waiting_rid()
                && self.slots.index(i)
        }

        #[invariant]
        pub fn response_stored_inv(self) -> bool {
            forall |i: nat| #[trigger] self.response_stored(i) ==>
                self.client_waiting(i)
                && self.responses.index(i).rid == self.clients.index(i).get_Waiting_rid()
                && !self.slots.index(i)
        }


        #[invariant]
        pub fn combiner_has_inv(self) -> bool {
            forall |i: nat| #[trigger] self.combiner_has(i) ==>
                self.client_waiting(i)
                && self.slots.index(i)
                && self.combiner_rid(i) == self.clients.index(i).get_Waiting_rid()
                && !self.request_stored(i)
        }

        init!{
            initialize(num_clients: nat) {
                init num_clients = num_clients;
                init clients = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| Client::Idle);
                init slots = IMap::new(
                    |i: nat| 0 <= i && i < num_clients,
                    |i: nat| false);
                init combiner = Combiner::Collecting { elems: Seq::empty() };
                init requests = IMap::empty();
                init responses = IMap::empty();
            }
        }

        #[inductive(initialize)]
        fn init_inductive(post: Self, num_clients: nat) { }

        ///// Client transitions

        transition!{
            client_send(j: nat, request: Request, cur_slot: bool) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'waiting' state
                remove clients -= [j => Client::Idle];
                add    clients += [j => Client::Waiting{rid: request.rid}];

                // Set the slot
                remove slots -= [j => cur_slot];
                add    slots += [j => true];

                // deposit the request
                deposit requests += [j => request] by {
                    assert(!pre.request_stored(j));
                };
            }
        }

        #[inductive(client_send)]
        fn client_send_inductive(pre: Self,
            post: Self, j: nat, request: Request, cur_slot: bool)
        {
            admit()
        }

        transition!{
            client_recv(j: nat) {
                require(0 <= j && j < pre.num_clients);

                // Move client to 'idle' state
                remove clients -= [j => let Client::Waiting{rid}];
                add    clients += [j => Client::Idle];

                // Check that the slot has been set back to 'false'
                have slots >= [j => false];

                // withdraw the response
                withdraw responses -= [j => let response] by {
                    assert(pre.client_waiting(j));
                    //assert(!pre.request_stored(j));
                    //assert(!pre.combiner_has(j));
                    //assert(pre.response_stored(j));
                };

                // make sure we get back the response for the correct request id:
                assert(response.rid == rid) by {
                    assert(pre.client_waiting(j));
                };
            }
        }

        #[inductive(client_recv)]
        fn client_recv_inductive(pre: Self, post: Self, j: nat) {
            admit()
        }

        ///// Combiner transitions

        transition!{
            combiner_recv() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // Observe that the slot has been set to 'true'
                have slots >= [j => true];

                // Withdraw a request
                withdraw requests -= [j => let request] by {
                    assert(pre.valid_idx(j));
                    assert(pre.client_waiting(j));
                    assert(pre.request_stored(j));
                };

                // Update combiner's local state to remember we withdrew a request with this ID
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::Some(request.rid)),
                };
            }
        }

        #[inductive(combiner_recv)]
        fn combiner_recv_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_skip() {
                require(pre.combiner.is_Collecting());
                let j = pre.combiner.get_Collecting_elems().len();
                require(0 <= j && j < pre.num_clients);

                // In practice, this happens when slot j is set to false, so we could add this:
                //    have slots >= [j => false];
                // but it's not necessary

                // Update combiner's local state to remember that we didn't withdraw
                // anything here.
                update combiner = Combiner::Collecting{
                    elems: pre.combiner.get_Collecting_elems().push(Option::None),
                };
            }
        }

        #[inductive(combiner_skip)]
        fn combiner_skip_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_go_to_responding() {
                require(pre.combiner.is_Collecting());
                require(pre.combiner.get_Collecting_elems().len() == pre.num_clients);
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Collecting_elems(),
                    idx: 0,
                };
            }
        }

        transition!{
            combiner_send(response: Response, cur_slot: bool) {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(response_opt == Option::Some(response.rid));

                // Set the slot back to false
                remove slots -= [j => cur_slot];
                add    slots += [j => false];

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };

                deposit responses += [j => response] by {
                    assert(pre.valid_idx(j));
                    assert(pre.combiner_has(j));
                    assert(!pre.response_stored(j));
                };
            }
        }

        #[inductive(combiner_send)]
        fn combiner_send_inductive(pre: Self, post: Self, response: Response, cur_slot: bool)
        {
            // The transition: combiner_send(j, response, cur_slot) where j = pre.combiner.get_Responding_idx()
            // modifies: slots[j], responses[j], and combiner.idx (from j to j+1)

            // Extract j from pre.combiner for use in the proof
            let j_val = pre.combiner.get_Responding_idx();

            // From the transition precondition, we know:
            // response_opt = pre.combiner.get_Responding_elems().index(j_val as int)
            // response_opt = Option::Some(response.rid)
            // So: pre.combiner.get_Responding_elems().index(j_val as int) = Option::Some(response.rid)

            // This means j_val < pre.combiner.get_Responding_elems().len()
            // And pre.combiner.get_Responding_elems().index(j_val as int).is_Some()

            // From pre invariant combiner_has_inv and pre.combiner_has(j_val):
            pre.combiner_has_inv();
            assert(pre.combiner_has(j_val));
            assert(pre.client_waiting(j_val));
            assert(pre.slots.index(j_val));
            assert(pre.combiner_rid(j_val) == pre.clients.index(j_val).get_Waiting_rid());
            assert(!pre.request_stored(j_val));

            // Now let's analyze what changed:
            // 1. slots[j_val] changed from cur_slot to false
            // 2. responses[j_val] is now Some(response)
            // 3. combiner changed from Responding{elems, idx=j_val} to Responding{elems, idx=j_val+1}

            // For all other indices i != j_val, the state is unchanged.

            // We need to prove all invariants in post.

            // 1. not_waiting_inv in post:
            // forall |i: nat| post.valid_idx(i) && post.clients[i].is_Idle() ==> !post.slots[i]
            // For i != j_val: post.clients[i] = pre.clients[i], post.slots[i] = pre.slots[i]
            // For i == j_val: post.slots[j_val] = false (we set it).
            broadcast use vstd::iset::group_iset_lemmas;
            broadcast use vstd::imap::group_imap_lemmas;
            broadcast use vstd::seq::group_seq_lemmas;

            // Helper: prove the key properties of the state change
            // From the transition: remove slots -= [j_val => cur_slot]; add slots += [j_val => false];
            // We need to show: post.slots = pre.slots.remove(j_val).insert(j_val, false)
            // So post.slots[j_val] = false, and for i != j_val, post.slots[i] = pre.slots[i]

            // Prove not_waiting_inv for all i
            proof fn not_waiting_proof(i: nat)
                requires post.valid_idx(i) && post.clients.index(i).is_Idle(),
                ensures !post.slots.index(i),
            {
                if i == j_val {
                    // i == j_val
                    // post.slots[j_val] = false (from transition)
                    assert(!post.slots.index(i));
                } else {
                    // i != j_val
                    // post.clients[i] = pre.clients[i]
                    // post.slots[i] = pre.slots[i]
                    // So post.clients[i].is_Idle() = pre.clients[i].is_Idle()
                    // By pre.not_waiting_inv: pre.clients[i].is_Idle() ==> !pre.slots[i]
                    // So !pre.slots[i], which means !post.slots[i]
                    assert(post.clients.index(i) == pre.clients.index(i));
                    assert(post.slots.index(i) == pre.slots.index(i));
                    assert(pre.clients.index(i).is_Idle());
                    assert(!pre.slots.index(i));
                }
            }

            // 2. waiting_inv in post:
            // forall |i: nat| post.client_waiting(i) ==> post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)
            // For i != j_val: All fields are unchanged. By pre.waiting_inv, the property holds.
            // For i == j_val: post.clients[j_val] = pre.clients[j_val] = Waiting(rid).
            //   So post.client_waiting(j_val) is true.
            //   post.responses[j_val] is now Some(response). So post.response_stored(j_val) is true.
            proof fn waiting_proof(i: nat)
                requires post.client_waiting(i),
                ensures post.request_stored(i) || post.response_stored(i) || post.combiner_has(i),
            {
                if i == j_val {
                    // i == j_val
                    // post.responses[j_val] = Some(response)
                    // So post.response_stored(j_val) is true
                    assert(post.response_stored(i));
                } else {
                    // i != j_val
                    // All fields unchanged
                    // By pre.waiting_inv
                    assert(pre.client_waiting(i));
                    assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));
                    assert(post.request_stored(i) == pre.request_stored(i));
                    assert(post.response_stored(i) == pre.response_stored(i));
                    assert(post.combiner_has(i) == pre.combiner_has(i));
                }
            }

            // 3. request_stored_inv in post:
            // forall |i: nat| post.request_stored(i) ==> post.client_waiting(i) && post.requests[i].rid == post.clients[i].rid && post.slots[i]
            // For i != j_val: All fields are unchanged. By pre.request_stored_inv, this holds.
            // For i == j_val: post.requests[j_val] = pre.requests[j_val].
            //   We know !pre.request_stored(j_val).
            proof fn request_stored_proof(i: nat)
                requires post.request_stored(i),
                ensures post.client_waiting(i) && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() && post.slots.index(i),
            {
                if i == j_val {
                    // i == j_val
                    // !pre.request_stored(j_val) and post.requests[j_val] = pre.requests[j_val]
                    // So !post.request_stored(j_val), contradiction with post.request_stored(i)
                    admit();
                } else {
                    // i != j_val
                    // All fields unchanged
                    // By pre.request_stored_inv
                    assert(pre.request_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.requests.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.slots.index(i));
                    assert(post.client_waiting(i) == pre.client_waiting(i));
                    assert(post.requests.index(i) == pre.requests.index(i));
                    assert(post.clients.index(i) == pre.clients.index(i));
                    assert(post.slots.index(i) == pre.slots.index(i));
                }
            }

            // 4. response_stored_inv in post:
            // forall |i: nat| post.response_stored(i) ==> post.client_waiting(i) && post.responses[i].rid == post.clients[i].rid && !post.slots[i]
            // For i != j_val: All fields are unchanged. By pre.response_stored_inv, this holds.
            // For i == j_val: post.responses[j_val] is now Some(response).
            //   We need: response.rid == pre.clients[j_val].get_Waiting_rid().
            //   This follows from pre.combiner_rid(j_val) == pre.clients[j_val].get_Waiting_rid()
            //   and pre.combiner_rid(j_val) = response_opt.get_Some_0() = response.rid.
            proof fn response_stored_proof(i: nat)
                requires post.response_stored(i),
                ensures post.client_waiting(i) && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() && !post.slots.index(i),
            {
                if i == j_val {
                    // i == j_val
                    // post.responses[j_val] = Some(response)
                    // post.clients[j_val] = pre.clients[j_val] = Waiting(rid)
                    // post.slots[j_val] = false
                    // We need: response.rid == pre.clients[j_val].get_Waiting_rid()
                    assert(post.responses.index(i) == response);
                    assert(post.clients.index(i) == pre.clients.index(i));
                    assert(pre.clients.index(i).is_Waiting());
                    assert(pre.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
                    assert(pre.combiner_rid(j_val) == pre.clients.index(j_val).get_Waiting_rid());
                    assert(pre.combiner_rid(j_val) == response_opt.get_Some_0());
                    assert(response_opt == Option::Some(response.rid));
                    assert(response.rid == response_opt.get_Some_0());
                    assert(response.rid == pre.combiner_rid(j_val));
                    assert(response.rid == pre.clients.index(j_val).get_Waiting_rid());
                    assert(post.clients.index(i).get_Waiting_rid() == pre.clients.index(i).get_Waiting_rid());
                    assert(post.slots.index(i) == false);
                } else {
                    // i != j_val
                    // All fields unchanged
                    // By pre.response_stored_inv
                    assert(pre.response_stored(i));
                    assert(pre.client_waiting(i));
                    assert(pre.responses.index(i).rid == pre.clients.index(i).get_Waiting_rid());
                    assert(!pre.slots.index(i));
                    assert(post.response_stored(i) == pre.response_stored(i));
                    assert(post.clients.index(i) == pre.clients.index(i));
                    assert(post.responses.index(i) == pre.responses.index(i));
                    assert(post.slots.index(i) == pre.slots.index(i));
                }
            }

            // 5. combiner_has_inv in post:
            // forall |i: nat| post.combiner_has(i) ==> post.client_waiting(i) && post.slots[i] && post.combiner_rid(i) == post.clients[i].rid && !post.request_stored(i)
            // For i < j_val or i == j_val: post.combiner_has(i) is false.
            // For i > j_val: post.combiner_has(i) = pre.combiner_has(i).
            proof fn combiner_has_proof(i: nat)
                requires post.combiner_has(i),
                ensures post.client_waiting(i) && post.slots.index(i) && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid() && !post.request_stored(i),
            {
                if i < j_val || i == j_val {
                    // i < j_val or i == j_val
                    // post.combiner_has(i) = false (because i < j_val+1 = post.combiner.idx)
                    assert(post.combiner_has(i) == false);
                    admit();
                } else {
                    // i > j_val (i >= j_val+1)
                    // post.combiner_has(i) = pre.combiner_has(i)
                    // All other properties unchanged
                    assert(post.combiner_has(i) == pre.combiner_has(i));
                    assert(pre.combiner_has(i));
                    assert(pre.client_waiting(i));
                    assert(pre.slots.index(i));
                    assert(pre.combiner_rid(i) == pre.clients.index(i).get_Waiting_rid());
                    assert(!pre.request_stored(i));
                    assert(post.client_waiting(i) == pre.client_waiting(i));
                    assert(post.slots.index(i) == pre.slots.index(i));
                    assert(post.combiner_rid(i) == pre.combiner_rid(i));
                    assert(post.clients.index(i) == pre.clients.index(i));
                    assert(post.requests.index(i) == pre.requests.index(i));
                }
            }

            // 6. slots_complete in post:
            // post.slots.dom() = pre.slots.dom() (removing and re-inserting the same key)
            proof fn slots_complete_proof(i: nat)
                requires (0 <= i && i < post.num_clients),
                ensures post.slots.dom().contains(i),
            {
                assert((0 <= i && i < pre.num_clients) == pre.slots.dom().contains(i)) by {
                    pre.slots_complete();
                };
                assert(post.num_clients == pre.num_clients);
                assert(post.slots == pre.slots.remove(j_val).insert(j_val, false));
                assert(post.slots.dom() == pre.slots.dom().remove(j_val).insert(j_val));
                assert(pre.slots.dom().remove(j_val).insert(j_val) == pre.slots.dom());
                assert(post.slots.dom().contains(i) == pre.slots.dom().contains(i));
            }

            // 7. clients_complete in post:
            // post.clients.dom() = pre.clients.dom()
            proof fn clients_complete_proof(i: nat)
                requires (0 <= i && i < post.num_clients),
                ensures post.clients.dom().contains(i),
            {
                assert((0 <= i && i < pre.num_clients) == pre.clients.dom().contains(i)) by {
                    pre.clients_complete();
                };
                assert(post.num_clients == pre.num_clients);
                assert(post.clients == pre.clients);
                assert(post.clients.dom() == pre.clients.dom());
            }

            // 8. clients_size in post:
            // post.combiner = Responding{elems, idx=j_val+1}
            proof fn clients_size_proof()
                ensures match post.combiner {
                    Combiner::Collecting{elems} => elems.len() <= post.num_clients,
                    Combiner::Responding{elems, idx} => elems.len() == post.num_clients && 0 <= idx && idx <= post.num_clients,
                },
            {
                assert(post.combiner == Combiner::Responding { elems: pre.combiner.get_Responding_elems(), idx: j_val + 1});
                assert(pre.combiner == Combiner::Responding { elems: let elems, idx: let idx });
                assert(pre.combiner.is_Responding());
                assert(pre.clients_size());
                assert(match pre.combiner {
                    Combiner::Collecting{elems} => elems.len() <= pre.num_clients,
                    Combiner::Responding{elems, idx} => elems.len() == pre.num_clients && 0 <= idx && idx <= pre.num_clients,
                });
                let pre_elems = pre.combiner.get_Responding_elems();
                let pre_idx = pre.combiner.get_Responding_idx();
                assert(pre_elems.len() == pre.num_clients);
                assert(0 <= pre_idx && pre_idx <= pre.num_clients);
                assert(post.combiner.get_Responding_elems().len() == pre_elems.len());
                assert(post.combiner.get_Responding_idx() == j_val + 1);
                assert(0 <= j_val);
                assert(j_val < pre.num_clients);
                assert(j_val + 1 <= pre.num_clients);
            }

            // All invariants hold!
            // Now we need to show the invariants by proving them for all cases
            // The best way is to use assert_by to prove forall properties

            // Prove not_waiting_inv
            assert(forall |i: nat| post.valid_idx(i) && post.clients.index(i).is_Idle() ==>
                !post.slots.index(i)) by {
                not_waiting_proof(i);
            }
            assert(post.not_waiting_inv());

            // Prove waiting_inv
            assert(forall |i: nat| post.client_waiting(i) ==>
                post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
                waiting_proof(i);
            }
            assert(post.waiting_inv());

            // Prove request_stored_inv
            assert(forall |i: nat| post.request_stored(i) ==>
                post.client_waiting(i) && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid() && post.slots.index(i)) by {
                request_stored_proof(i);
            }
            assert(post.request_stored_inv());

            // Prove response_stored_inv
            assert(forall |i: nat| post.response_stored(i) ==>
                post.client_waiting(i) && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid() && !post.slots.index(i)) by {
                response_stored_proof(i);
            }
            assert(post.response_stored_inv());

            // Prove combiner_has_inv
            assert(forall |i: nat| post.combiner_has(i) ==>
                post.client_waiting(i) && post.slots.index(i) && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid() && !post.request_stored(i)) by {
                combiner_has_proof(i);
            }
            assert(post.combiner_has_inv());

            // Prove slots_complete
            assert(forall |i: nat| (0 <= i && i < post.num_clients) == post.slots.dom().contains(i)) by {
                slots_complete_proof(i);
            }
            assert(post.slots_complete());

            // Prove clients_complete
            assert(forall |i: nat| (0 <= i && i < post.num_clients) == post.clients.dom().contains(i)) by {
                clients_complete_proof(i);
            }
            assert(post.clients_complete());

            // Prove clients_size
            assert(match post.combiner {
                Combiner::Collecting{elems} => elems.len() <= post.num_clients,
                Combiner::Responding{elems, idx} => elems.len() == post.num_clients && 0 <= idx && idx <= post.num_clients,
            }) by {
                clients_size_proof();
            }
            assert(post.clients_size());

            // All invariants hold!
        }

        transition!{
            combiner_send_skip() {
                require(pre.combiner.is_Responding());
                let j = pre.combiner.get_Responding_idx();
                require(0 <= j && j < pre.num_clients);
                let response_opt = pre.combiner.get_Responding_elems().index(j as int);

                // The response we return has to have the right request ID
                require(equal(response_opt, Option::None));

                // Update the combiner's local state
                update combiner = Combiner::Responding{
                    elems: pre.combiner.get_Responding_elems(),
                    idx: j + 1,
                };
            }
        }

        #[inductive(combiner_send_skip)]
        fn combiner_send_skip_inductive(pre: Self, post: Self) {
            admit()
        }

        #[inductive(combiner_go_to_responding)]
        fn combiner_go_to_responding_inductive(pre: Self, post: Self) {
            admit()
        }

        transition!{
            combiner_go_to_collecting() {
                require(pre.combiner.is_Responding());
                require(pre.combiner.get_Responding_idx() == pre.num_clients);
                update combiner = Combiner::Collecting{ elems: Seq::empty() };
            }
        }

        #[inductive(combiner_go_to_collecting)]
        fn combiner_go_to_collecting_inductive(pre: Self, post: Self) {
            admit()
        }

    }
}

fn main() {}

